using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using ZOSAPI;
using ZOSAPI.Editors.LDE;
using ZOSAPI_NetHelper;

// Generic standalone runner for packages generated by the eye experiment app.
// It intentionally uses only the ZOS-API calls already exercised by the
// repository's live OpticStudio 24.1 validation.
public static class ZosApiEyeBatch
{
    private sealed class BatchCase
    {
        public string CaseId;
        public string EyeId;
        public string Mode;
        public double WavelengthNm;
        public double SourceDemandD;
        public double SourceDistanceMm;
        public double FocalLengthMm;
        public double AxialLengthMm;
        public double ImageIndex;
        public double ReducedRetinaDistanceMm;
        public double TargetDiameterMm;
        public double PupilDiameterMm;
        public double ExternalLensPowerD;
        public double ExternalLensVertexDistanceMm;
        public double SourceDiameterMm;
        public double SourceCoefficient;
        public double PupilCoefficient;
        public string InputSha256;
    }

    private sealed class CaseResult
    {
        public double ExpectedMinYmm;
        public double ObservedMinYmm;
        public double ExpectedMaxYmm;
        public double ObservedMaxYmm;
        public double BoundaryErrorUm;
        public int ValidRays;
        public int RayErrors;
        public int VignettedRays;
        public string ZosFile;
        public string ZosSha256;
    }

    public static int Main(string[] args)
    {
        string installDir = Environment.GetEnvironmentVariable("ZEMAX_OPTICSTUDIO_DIR");
        string casesPath = Argument(args, "--cases");
        string outputDir = Argument(args, "--output");
        string batchId = Argument(args, "--batch-id");
        if (String.IsNullOrWhiteSpace(installDir) || !Directory.Exists(installDir))
            return Fail("ZEMAX_OPTICSTUDIO_DIR must identify the installed OpticStudio directory.", 2);
        if (String.IsNullOrWhiteSpace(casesPath) || !File.Exists(casesPath))
            return Fail("--cases must identify an existing cases.csv file.", 3);
        if (String.IsNullOrWhiteSpace(outputDir) || !Directory.Exists(outputDir))
            return Fail("--output must identify a newly created output directory.", 4);
        if (String.IsNullOrWhiteSpace(batchId))
            return Fail("--batch-id is required.", 5);

        DateTime startedUtc = DateTime.UtcNow;
        IZOSAPI_Application application = null;
        int completed = 0;
        int failed = 0;
        string version = "unknown";
        bool apiLicenseValid = false;
        var cases = ReadCases(casesPath);
        string resultsPath = Path.Combine(outputDir, "zos_results.csv");
        string systemsDir = Path.Combine(outputDir, "systems");
        Directory.CreateDirectory(systemsDir);

        try
        {
            if (!ZOSAPI_Initializer.Initialize(installDir))
                throw new InvalidOperationException("Unable to initialize OpticStudio from the supplied directory.");
            application = new ZOSAPI_Connection().CreateNewApplication();
            if (application == null)
                throw new InvalidOperationException("CreateNewApplication returned null.");
            apiLicenseValid = application.IsValidLicenseForAPI;
            if (!apiLicenseValid)
                throw new InvalidOperationException("A valid ZOS-API license is required.");
            version = application.ZOSMajorVersion + "." + application.ZOSMinorVersion + "." + application.ZOSSPVersion;

            using (var writer = new StreamWriter(resultsPath, false, new UTF8Encoding(false)))
            {
                writer.WriteLine("batch_id,case_id,input_sha256,opticstudio_version,api_license_valid,expected_min_y_mm,observed_min_y_mm,expected_max_y_mm,observed_max_y_mm,boundary_error_um,valid_rays,ray_error_count,ray_vignette_count,zos_file,zos_sha256,status,error_type,error_message");
                foreach (BatchCase item in cases)
                {
                    try
                    {
                        CaseResult result = RunCase(application, systemsDir, item);
                        WriteResult(writer, batchId, item, version, apiLicenseValid, result);
                        completed++;
                    }
                    catch (Exception ex)
                    {
                        WriteError(writer, batchId, item, version, apiLicenseValid, ex);
                        failed++;
                    }
                    writer.Flush();
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("ERROR_TYPE=" + ex.GetType().FullName);
            Console.Error.WriteLine("ERROR_MESSAGE=" + ex.Message);
            WriteRunMetadata(outputDir, batchId, startedUtc, DateTime.UtcNow, casesPath, version, apiLicenseValid, cases.Count, completed, Math.Max(1, failed));
            return 1;
        }
        finally
        {
            if (application != null) application.CloseApplication();
        }

        WriteRunMetadata(outputDir, batchId, startedUtc, DateTime.UtcNow, casesPath, version, apiLicenseValid, cases.Count, completed, failed);
        Console.WriteLine("ZEMAX_BATCH_ID=" + batchId);
        Console.WriteLine("ZEMAX_RESULTS_CSV=" + resultsPath);
        Console.WriteLine("COMPLETED_CASES=" + completed.ToString(CultureInfo.InvariantCulture));
        Console.WriteLine("FAILED_CASES=" + failed.ToString(CultureInfo.InvariantCulture));
        return failed == 0 ? 0 : 1;
    }

    private static CaseResult RunCase(IZOSAPI_Application application, string systemsDir, BatchCase item)
    {
        IOpticalSystem system = application.PrimarySystem;
        system.New(false);
        system.SystemData.Aperture.ApertureValue = item.PupilDiameterMm;
        system.SystemData.Fields.SetFieldType(ZOSAPI.SystemData.FieldType.ObjectHeight);
        ZOSAPI.SystemData.IField field = system.SystemData.Fields.GetField(1);
        field.X = 0.0;
        field.Y = item.SourceDiameterMm / 2.0;
        system.SystemData.Wavelengths.GetWavelength(1).Wavelength = item.WavelengthNm / 1000.0;

        ILDERow objectSurface = system.LDE.GetSurfaceAt(0);
        ILDERow eyeSurface;
        if (Math.Abs(item.ExternalLensPowerD) > 1e-15)
        {
            if (item.ExternalLensVertexDistanceMm <= 0.0 || item.ExternalLensVertexDistanceMm >= item.SourceDistanceMm)
                throw new InvalidOperationException("External lens vertex must lie strictly between source and eye.");
            system.LDE.InsertNewSurfaceAt(2);
            ILDERow externalSurface = system.LDE.GetSurfaceAt(1);
            eyeSurface = system.LDE.GetSurfaceAt(2);
            objectSurface.Thickness = item.SourceDistanceMm - item.ExternalLensVertexDistanceMm;
            ConfigureParaxial(externalSurface, 1000.0 / item.ExternalLensPowerD);
            externalSurface.Thickness = item.ExternalLensVertexDistanceMm;
            externalSurface.SemiDiameter = Math.Max(item.SourceDiameterMm, item.PupilDiameterMm);
        }
        else
        {
            objectSurface.Thickness = item.SourceDistanceMm;
            eyeSurface = system.LDE.GetSurfaceAt(1);
        }
        ConfigureParaxial(eyeSurface, item.FocalLengthMm);
        eyeSurface.IsStop = true;
        eyeSurface.Thickness = item.ReducedRetinaDistanceMm;
        eyeSurface.SemiDiameter = item.PupilDiameterMm / 2.0;

        string zosName = item.CaseId + ".zos";
        string zosPath = Path.Combine(systemsDir, zosName);
        if (File.Exists(zosPath))
            throw new IOException("Refusing to overwrite existing system: " + zosName);
        system.SaveAs(zosPath);

        var raytrace = system.Tools.OpenBatchRayTrace();
        int lastSurface = system.LDE.NumberOfSurfaces;
        // Direct rays make the physical ray height at the eye stop explicit.
        // This is important with an external negative lens: normalized pupil
        // coordinates refer to the entrance pupil and would silently test a
        // different mapping from the ABCD contract used by the application.
        var data = raytrace.CreateDirectUnpol(4, ZOSAPI.Tools.RayTrace.RaysType.Paraxial, 0, lastSurface);
        foreach (double hy in new double[] { -1.0, 1.0 })
            foreach (double py in new double[] { -0.99, 0.99 })
            {
                double sourceY = hy * item.SourceDiameterMm / 2.0;
                double pupilY = py * item.PupilDiameterMm / 2.0;
                double[] pre = PreEyeHeightMatrix(item);
                double slope = (pupilY - pre[0] * sourceY) / pre[1];
                double directionScale = 1.0 / Math.Sqrt(1.0 + slope * slope);
                data.AddRay(1, 0.0, sourceY, 0.0, 0.0, slope * directionScale, directionScale);
            }
        raytrace.RunAndWaitForCompletion();
        data.StartReadingResults();

        int rayNumber, errorCode, vignetteCode;
        double x, y, z, l, m, n, l2, m2, n2, intensity;
        int rayErrors = 0;
        int vignetted = 0;
        var ys = new List<double>();
        bool success = data.ReadNextResult(out rayNumber, out errorCode, out vignetteCode, out x, out y, out z, out l, out m, out n, out l2, out m2, out n2, out intensity);
        while (success)
        {
            if (errorCode != 0) rayErrors++;
            if (vignetteCode != 0) vignetted++;
            if (errorCode == 0 && vignetteCode == 0) ys.Add(y);
            success = data.ReadNextResult(out rayNumber, out errorCode, out vignetteCode, out x, out y, out z, out l, out m, out n, out l2, out m2, out n2, out intensity);
        }
        raytrace.Close();
        if (ys.Count != 4)
            throw new InvalidOperationException("Expected four valid unvignetted rays; observed " + ys.Count.ToString(CultureInfo.InvariantCulture) + ".");
        ys.Sort();

        double[] expected = ExpectedBounds(item);
        double errorUm = 1000.0 * Math.Max(Math.Abs(ys[0] - expected[0]), Math.Abs(ys[ys.Count - 1] - expected[1]));
        return new CaseResult {
            ExpectedMinYmm = expected[0], ObservedMinYmm = ys[0],
            ExpectedMaxYmm = expected[1], ObservedMaxYmm = ys[ys.Count - 1],
            BoundaryErrorUm = errorUm, ValidRays = ys.Count,
            RayErrors = rayErrors, VignettedRays = vignetted,
            ZosFile = "systems/" + zosName, ZosSha256 = Sha256(zosPath)
        };
    }

    private static double[] ExpectedBounds(BatchCase item)
    {
        double sourceRadius = item.SourceDiameterMm / 2.0;
        double pupilRadius = item.PupilDiameterMm / 2.0;
        var values = new List<double>();
        foreach (double hy in new double[] { -1.0, 1.0 })
            foreach (double py in new double[] { -0.99, 0.99 })
                values.Add(item.SourceCoefficient * hy * sourceRadius + item.PupilCoefficient * py * pupilRadius);
        values.Sort();
        return new double[] { values[0], values[values.Count - 1] };
    }

    private static double[] PreEyeHeightMatrix(BatchCase item)
    {
        if (Math.Abs(item.ExternalLensPowerD) <= 1e-15)
            return new double[] { 1.0, item.SourceDistanceMm };
        double vertexM = item.ExternalLensVertexDistanceMm / 1000.0;
        double sourceToLensMm = item.SourceDistanceMm - item.ExternalLensVertexDistanceMm;
        double a = 1.0 - vertexM * item.ExternalLensPowerD;
        double bMm = item.SourceDistanceMm - vertexM * item.ExternalLensPowerD * sourceToLensMm;
        return new double[] { a, bMm };
    }

    private static void ConfigureParaxial(ILDERow surface, double focalLengthMm)
    {
        ISurfaceTypeSettings settings = surface.GetSurfaceTypeSettings(SurfaceType.Paraxial);
        surface.ChangeType(settings);
        ISurfaceParaxial data = surface.SurfaceData as ISurfaceParaxial;
        if (data == null) throw new InvalidOperationException("Unable to obtain paraxial surface data.");
        data.FocalLength = focalLengthMm;
    }

    private static List<BatchCase> ReadCases(string path)
    {
        string[] lines = File.ReadAllLines(path, new UTF8Encoding(false));
        if (lines.Length < 2) throw new InvalidDataException("cases.csv has no data rows.");
        string expectedHeader = "case_id,eye_id,mode,wavelength_nm,source_demand_D,source_distance_mm,effective_focal_length_mm,axial_length_mm,image_index,reduced_retina_distance_mm,target_diameter_mm,pupil_diameter_mm,external_lens_power_D,external_lens_vertex_distance_mm,conservative_source_diameter_mm,source_mapping_coefficient,pupil_mapping_coefficient,input_sha256";
        if (!String.Equals(lines[0].Trim(), expectedHeader, StringComparison.Ordinal))
            throw new InvalidDataException("cases.csv header does not match schema 1.0.");
        var result = new List<BatchCase>();
        var ids = new HashSet<string>(StringComparer.Ordinal);
        for (int index = 1; index < lines.Length; index++)
        {
            if (String.IsNullOrWhiteSpace(lines[index])) continue;
            string[] cells = lines[index].Split(',');
            if (cells.Length != 18) throw new InvalidDataException("Invalid column count at cases.csv row " + (index + 1));
            if (!ids.Add(cells[0])) throw new InvalidDataException("Duplicate case_id: " + cells[0]);
            result.Add(new BatchCase {
                CaseId=cells[0], EyeId=cells[1], Mode=cells[2], WavelengthNm=D(cells[3]),
                SourceDemandD=D(cells[4]), SourceDistanceMm=D(cells[5]), FocalLengthMm=D(cells[6]),
                AxialLengthMm=D(cells[7]), ImageIndex=D(cells[8]), ReducedRetinaDistanceMm=D(cells[9]),
                TargetDiameterMm=D(cells[10]), PupilDiameterMm=D(cells[11]), ExternalLensPowerD=D(cells[12]),
                ExternalLensVertexDistanceMm=D(cells[13]), SourceDiameterMm=D(cells[14]),
                SourceCoefficient=D(cells[15]), PupilCoefficient=D(cells[16]), InputSha256=cells[17]
            });
        }
        return result;
    }

    private static void WriteResult(StreamWriter writer, string batchId, BatchCase item, string version, bool validLicense, CaseResult result)
    {
        writer.WriteLine(String.Join(",", new string[] {
            Csv(batchId), Csv(item.CaseId), Csv(item.InputSha256), Csv(version), validLicense.ToString().ToLowerInvariant(),
            F(result.ExpectedMinYmm), F(result.ObservedMinYmm), F(result.ExpectedMaxYmm), F(result.ObservedMaxYmm), F(result.BoundaryErrorUm),
            result.ValidRays.ToString(CultureInfo.InvariantCulture), result.RayErrors.ToString(CultureInfo.InvariantCulture),
            result.VignettedRays.ToString(CultureInfo.InvariantCulture), Csv(result.ZosFile), Csv(result.ZosSha256),
            "OK", "", ""
        }));
    }

    private static void WriteError(StreamWriter writer, string batchId, BatchCase item, string version, bool validLicense, Exception ex)
    {
        writer.WriteLine(String.Join(",", new string[] {
            Csv(batchId), Csv(item.CaseId), Csv(item.InputSha256), Csv(version), validLicense.ToString().ToLowerInvariant(),
            "", "", "", "", "", "0", "0", "0", "", "", "ERROR", Csv(ex.GetType().FullName), Csv(ex.Message)
        }));
    }

    private static void WriteRunMetadata(string outputDir, string batchId, DateTime startedUtc, DateTime completedUtc, string casesPath, string version, bool license, int total, int completed, int failed)
    {
        string json = "{" +
            "\"schema_version\":\"1.0\"," +
            "\"batch_id\":" + Json(batchId) + "," +
            "\"started_utc\":" + Json(startedUtc.ToString("o", CultureInfo.InvariantCulture)) + "," +
            "\"completed_utc\":" + Json(completedUtc.ToString("o", CultureInfo.InvariantCulture)) + "," +
            "\"cases_sha256\":" + Json(Sha256(casesPath)) + "," +
            "\"opticstudio_version\":" + Json(version) + "," +
            "\"api_license_valid\":" + license.ToString().ToLowerInvariant() + "," +
            "\"total_cases\":" + total.ToString(CultureInfo.InvariantCulture) + "," +
            "\"completed_cases\":" + completed.ToString(CultureInfo.InvariantCulture) + "," +
            "\"failed_cases\":" + failed.ToString(CultureInfo.InvariantCulture) +
            "}\n";
        File.WriteAllText(Path.Combine(outputDir, "run_metadata.json"), json, new UTF8Encoding(false));
    }

    private static string Argument(string[] args, string name)
    {
        for (int index = 0; index + 1 < args.Length; index++)
            if (String.Equals(args[index], name, StringComparison.Ordinal)) return args[index + 1];
        return null;
    }

    private static int Fail(string message, int code) { Console.Error.WriteLine(message); return code; }
    private static double D(string value) { return Double.Parse(value, NumberStyles.Float, CultureInfo.InvariantCulture); }
    private static string F(double value) { return value.ToString("G17", CultureInfo.InvariantCulture); }
    private static string Csv(string value) { return "\"" + (value ?? "").Replace("\"", "\"\"") + "\""; }
    private static string Json(string value) { return "\"" + (value ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\r", "\\r").Replace("\n", "\\n") + "\""; }

    private static string Sha256(string path)
    {
        using (var stream = File.OpenRead(path))
        using (var sha = SHA256.Create())
        {
            byte[] hash = sha.ComputeHash(stream);
            var text = new StringBuilder(hash.Length * 2);
            foreach (byte item in hash) text.Append(item.ToString("x2", CultureInfo.InvariantCulture));
            return text.ToString();
        }
    }
}
